document.addEventListener("DOMContentLoaded", () => {
  const popupB = document.getElementById('popup-multi-b');
  if (!popupB) return;

  const form       = document.getElementById('wf-form-Multi-step-form-b');
  const ineligible = popupB.querySelector('.default-inelegible');
  const eligible   = popupB.querySelector('.default-elegible');
  const radios     = popupB.querySelectorAll('input[name="Image-choice"]');
  const emailInput = popupB.querySelector('#multi-email-b');
  const submitBtn  = popupB.querySelector('#popup-multi-submit');

  // --- Блокування email та сабміту до вибору варіанту ---
  const setLocked = (locked) => {
    if (locked) {
      emailInput.setAttribute('disabled', 'disabled');
      emailInput.setAttribute('placeholder', 'Please select an option above first');
      emailInput.style.opacity = '0.5';
      emailInput.style.cursor  = 'not-allowed';
      if (submitBtn) {
        submitBtn.setAttribute('disabled', 'disabled');
        submitBtn.style.opacity = '0.5';
        submitBtn.style.cursor  = 'not-allowed';
      }
    } else {
      emailInput.removeAttribute('disabled');
      emailInput.setAttribute('placeholder', '*Email address');
      emailInput.style.opacity = '';
      emailInput.style.cursor  = '';
      if (submitBtn) {
        submitBtn.removeAttribute('disabled');
        submitBtn.style.opacity = '';
        submitBtn.style.cursor  = '';
      }
    }
  };

  // Стартовий стан — заблоковано
  setLocked(true);

  // Розблокування при виборі будь-якого радіо
  radios.forEach(radio => {
    radio.addEventListener('change', () => {
      const anyChecked = Array.from(radios).some(r => r.checked);
      setLocked(!anyChecked);
    });
  });

  // Захист на сабміті — якщо нічого не обрано, блокуємо відправку
  form.addEventListener('submit', (e) => {
    const anyChecked = Array.from(radios).some(r => r.checked);
    if (!anyChecked) {
      e.preventDefault();
      e.stopPropagation();
      return false;
    }
  }, true);

  // --- Існуюча логіка eligible/ineligible ---
  form.addEventListener('submit', () => {
    const patchyChecked   = popupB.querySelector('#Patchy').checked;
    const completeChecked = popupB.querySelector('#Complete').checked;

    if (patchyChecked || completeChecked) {
      ineligible.style.display = 'block';
      eligible.style.display   = 'none';
    } else {
      ineligible.style.display = 'none';
      eligible.style.display   = 'block';
    }
  });

  // --- Існуюча логіка active state ---
  const checkboxes = popupB.querySelectorAll('.fs-checkbox_button-5');
  checkboxes.forEach(checkbox => {
    checkbox.addEventListener('change', () => {
      checkboxes.forEach(cb => cb.closest('.fs-checkbox_field-5').classList.remove('is-active'));
      checkbox.closest('.fs-checkbox_field-5').classList.add('is-active');
    });
  });
});

