function initPopup({ popupId, formId, emailId, modalName }) {
  const popup = document.getElementById(popupId);
  if (!popup) return;

  const form        = document.getElementById(formId);
  const emailEl      = popup.querySelector(`#${emailId}`);
  const mPrev        = popup.querySelector('[id$="-prev"]');
  const mClose       = popup.querySelector('[id*="-close"]');
  const mContinue    = popup.querySelector('[id$="-continue"]');
  const mNext        = popup.querySelector('[id$="-next"]');
  const mLeadClose   = popup.querySelectorAll('[data-modal-lead-close]');
  const mStep1       = popup.querySelector('.popup-multi-step.step-1');
  const mStep2       = popup.querySelector('.popup-multi-step.step-2');
  const copyBtn      = popup.querySelector('[id$="-copy-btn"]');
  const couponEl     = popup.querySelector('[id$="-coupon"]');
  const couponField  = popup.querySelector('input[name="coupon"]');
  const nextStepBtn  = popup.querySelector('#next-step-button');

  // --- Helper: get coupon (URL takes priority, else fall back to hidden field default) ---
  const getActiveCoupon = () => {
    const urlCoupon = new URLSearchParams(window.location.search).get('coupon');
    if (urlCoupon) return urlCoupon;
    if (couponField && couponField.value) return couponField.value;
    return '';
  };

  // --- Helper: append/replace coupon param in a URL ---
  const setCouponInUrl = (urlStr, coupon) => {
    if (!coupon) return urlStr;
    try {
      // Handle relative URLs by using a dummy base
      const isRelative = urlStr.startsWith('/');
      const base = isRelative ? window.location.origin : undefined;
      const u = new URL(urlStr, base);
      u.searchParams.set('coupon', coupon);
      return isRelative ? u.pathname + u.search + u.hash : u.toString();
    } catch (e) {
      // Fallback for any weird URLs
      const sep = urlStr.includes('?') ? '&' : '?';
      return urlStr + sep + 'coupon=' + encodeURIComponent(coupon);
    }
  };

  // --- FIX 1: Override hardcoded coupon in hidden field with URL param ---
  const urlCoupon = new URLSearchParams(window.location.search).get('coupon');
  if (urlCoupon && couponField) {
    couponField.value = urlCoupon;
  }

  // --- FIX 2: Set coupon on the "Next step" CTA href (so /n/hair-loss/quiz keeps the coupon) ---
  const updateNextStepHref = () => {
    if (!nextStepBtn) return;
    const baseHref = nextStepBtn.getAttribute('data-base-href') || nextStepBtn.getAttribute('href');
    // Cache original href once so we don't keep appending
    if (!nextStepBtn.getAttribute('data-base-href')) {
      nextStepBtn.setAttribute('data-base-href', baseHref);
    }
    const coupon = getActiveCoupon();
    nextStepBtn.setAttribute('href', setCouponInUrl(baseHref, coupon));
  };
  updateNextStepHref();

  // Populate hidden fields on email change
  emailEl.addEventListener('change', () => {
    popup.querySelector('.SID').value       = getCookieValue('manual-sid');
    popup.querySelector('.page_path').value = window.location.href;

    // Re-check URL coupon (safety net for SPA navigation)
    const freshUrlCoupon = new URLSearchParams(window.location.search).get('coupon');
    if (freshUrlCoupon && couponField) {
      couponField.value = freshUrlCoupon;
    }
    updateNextStepHref();
  });

  // Init step visibility
  mStep1.style.display = 'block';
  if (mStep2) mStep2.style.display = 'none';
  if (mPrev)  mPrev.style.display  = 'none';

  // Auto-open after delay
  setTimeout(() => {
    popup.classList.add('visible');
    document.body.classList.add('no-scroll');
    window.dataLayer.push({
      event: 'Modal Opened',
      is_custom_track: true,
      event_params: { modal_name: modalName },
    });
  }, 20000);

  // Navigation
  if (mNext) mNext.addEventListener('click', () => {
    mStep1.style.display = 'none';
    mStep2.style.display = 'block';
    if (mPrev) mPrev.style.display = 'flex';
  });
  if (mPrev) mPrev.addEventListener('click', () => {
    mStep1.style.display = 'block';
    mStep2.style.display = 'none';
    mPrev.style.display  = 'none';
  });

  const closePopup = () => {
    popup.classList.remove('visible');
    document.body.classList.remove('no-scroll');
  };
  if (mClose)    mClose.addEventListener('click', closePopup);
  if (mContinue) mContinue.addEventListener('click', closePopup);
  mLeadClose.forEach(el => el.addEventListener('click', closePopup));

  // Form submit
  form.addEventListener('submit', (e) => {
    e.preventDefault();

    // --- FIX 3: Final guard — refresh next-step href right before showing success screen ---
    const submitUrlCoupon = new URLSearchParams(window.location.search).get('coupon');
    if (couponField && submitUrlCoupon) {
      couponField.value = submitUrlCoupon;
    }
    updateNextStepHref();

    const finalCoupon = getActiveCoupon();

    if (mPrev) mPrev.style.display = 'none';

    window.dataLayer.push({
      event: 'email_captured',
      is_custom_track: true,
      event_params: {
        type: 'email',
        capture_type: 'pop-up',
        coupon: finalCoupon,
      },
      user_params:  { email: emailEl.value },
    });
    window.dataLayer.push({
      event: 'Modal Submitted',
      is_custom_track: true,
      event_params: {
        email:      emailEl.value,
        modal_name: modalName,
        page_path:  window.location.href,
        coupon:     finalCoupon,
      },
    });
  });

  // Copy coupon button
  if (copyBtn && couponEl) {
    copyBtn.addEventListener('click', () => {
      navigator.clipboard.writeText(couponEl.textContent.trim())
        .then(() => {
          copyBtn.classList.add('show');
          setTimeout(() => copyBtn.classList.remove('show'), 3000);
        })
        .catch(err => console.error('Failed to copy:', err));
    });
  }
}

