document.addEventListener('DOMContentLoaded', () => {
    // URL params — coupon/channel override
    const params = new URLSearchParams(window.location.search);
    const urlCoupon = params.get('coupon');
    if (urlCoupon) {
      document.querySelectorAll('input.coupon').forEach(el => el.value = urlCoupon);
    }
    const urlChannel = params.get('channel');
    if (urlChannel) {
      document.querySelectorAll('input.channel').forEach(el => el.value = urlChannel);
    }

    // ============================================================
    // POPUP (female hair loss type selector)
    // ============================================================
    const popup = document.getElementById('popup-multi-b');
    if (!popup) return;

    const form = document.getElementById('wf-form-Multi-step-form-b');
    const ineligible = popup.querySelector('.default-inelegible');
    const eligible = popup.querySelector('.default-elegible');
    const radios = popup.querySelectorAll('input[name="Image-choice"]');
    const patchyRadio = popup.querySelector('#Patchy-hair-loss');
    const emailInput = popup.querySelector('#multi-email-b');
    const submitBtn = popup.querySelector('#popup-multi-submit');
    const closeBtn = popup.querySelector('#popup-multi-close-b');
    const modalName = 'Multi step popup form';

    const anyRadioChecked = () => Array.from(radios).some(r => r.checked);

    // Lock email + submit until a hair loss type is selected
    const setLocked = (locked) => {
      if (locked) {
        emailInput.setAttribute('disabled', 'disabled');
        emailInput.setAttribute('placeholder', 'Please select an option above first');
      } else {
        emailInput.removeAttribute('disabled');
        emailInput.setAttribute('placeholder', '*Email address');
      }
      emailInput.style.opacity = locked ? '0.5' : '';
      emailInput.style.cursor = locked ? 'not-allowed' : '';
      if (submitBtn) {
        submitBtn.toggleAttribute('disabled', locked);
        submitBtn.style.opacity = locked ? '0.5' : '';
        submitBtn.style.cursor = locked ? 'not-allowed' : '';
      }
    };
    setLocked(true);

    // Unlock on selection + active state on the selected option
    radios.forEach(radio => {
      radio.addEventListener('change', () => {
        setLocked(!anyRadioChecked());
        radios.forEach(r => {
          const field = r.closest('.fs-checkbox_field-5');
          if (field) field.classList.toggle('is-active', r.checked);
        });
      });
    });

    // Close
    const closePopup = () => {
      popup.classList.remove('visible');
      document.body.classList.remove('no-scroll');
    };
    if (closeBtn) closeBtn.addEventListener('click', closePopup);
    popup.querySelectorAll('[close-popup]').forEach(el => {
      el.addEventListener('click', (e) => {
        e.preventDefault();
        closePopup();
      });
    });

    // Submit — capture phase so it runs before Webflow's form handler
    form.addEventListener('submit', (e) => {
      if (!anyRadioChecked()) {
        e.preventDefault();
        e.stopPropagation();
        return;
      }

      const isIneligible = patchyRadio && patchyRadio.checked;
      ineligible.style.display = isIneligible ? 'block' : 'none';
      eligible.style.display = isIneligible ? 'none' : 'block';

      popup.querySelector('.SID').value = getCookieValue('manual-sid');
      popup.querySelector('.page_path').value = window.location.href;

      window.dataLayer.push({
        event: 'email_captured',
        is_custom_track: true,
        event_params: { type: 'email', capture_type: 'pop-up' },
        user_params: { email: emailInput.value },
      });
      window.dataLayer.push({
        event: 'Modal Submitted',
        is_custom_track: true,
        event_params: {
          email: emailInput.value,
          modal_name: modalName,
          page_path: window.location.href,
        },
      });
    }, true);

    // Auto-open after 7s
    setTimeout(() => {
      popup.classList.add('visible');
     // document.body.classList.add('no-scroll');
      window.dataLayer.push({
        event: 'Modal Opened',
        is_custom_track: true,
        event_params: { modal_name: modalName },
      });
    }, 7000);
  });
